#pragma once

#include "CoreMinimal.h"

class UNiagaraSystem;

/**
 * Reads / writes Niagara node parameter snapshots.
 *
 * Snapshot semantics:
 *  - Every editable node property and every graph pin is written to the JSON file.
 *  - A value is marked "modified" when it differs from its default:
 *      * Graph pins use UEdGraphPin::AutogeneratedDefaultValue as the default.
 *      * Node properties use the class default object (CDO) as the default.
 *
 * Restore semantics:
 *  - The original system referenced by the snapshot is duplicated to a new asset.
 *  - All recorded node properties and unlinked pin values are written back so the
 *    new asset matches the snapshot exactly.
 *  - The "modified" flags are kept in the file for inspection only.
 */
class FCommonEFXExporter
{
public:
	/** Lets the user pick a Niagara system in the Content Browser and export it. */
	static bool ExportSelectedSystemToFile(FString& OutFile, FString& OutError);

	/** Exports a specific system. Prompts for the destination JSON file. */
	static bool ExportSystemToFileWithDialog(UNiagaraSystem* System, FString& OutFile, FString& OutError);

	/** Exports a specific system to a specific JSON file. */
	static bool ExportSystemToFile(UNiagaraSystem* System, const FString& FileName, FString& OutError);

	/** Prompts for a snapshot file and restores it into a newly duplicated system asset. */
	static bool ImportSystemFromFileWithDialog(FString& OutNewAssetPath, FString& OutError);

	/** Restores a snapshot from a specific file. Returns the newly created system. */
	static UNiagaraSystem* ImportSystemFromFile(const FString& FileName, FString& OutError);
};
